-- introSentences: when each sentence of the narration starts, for the subtitles.
ST.introSentences = {
    [1] = {
        { t = 0.42, text = [=[The Cosmic Index of Summonable Persons is, by general agreement, the most important document in Azeroth that nobody has ever read.]=] },
        { t = 10.41, text = [=[It lists every being that may legally be summoned, in alphabetical order, and it was compiled by a single clerk who had, at the time, been on shift for nine thousand years.]=] },
    },
    [2] = {
        { t = 0.41, text = [=[Somewhere around the letter Z, the clerk sneezed.]=] },
        { t = 4.80, text = [=[This is generally accepted to be the origin of the entire problem.]=] },
    },
    [3] = {
        { t = 0.41, text = [=[As a result of the sneeze, a Licensed Summoning Liaison, Third Class, named Zennit was entered into the Index as the default recipient of every Ritual of Summoning completed within range of his name.]=] },
        { t = 14.60, text = [=[This includes rituals meant for other people.]=] },
        { t = 18.65, text = [=[It includes rituals meant for nobody.]=] },
        { t = 22.38, text = [=[It includes at least one ritual intended for a goat.]=] },
    },
    [4] = {
        { t = 0.41, text = [=[Zennit did what any reasonable person would do.]=] },
        { t = 4.76, text = [=[He looked for the form.]=] },
        { t = 7.47, text = [=[The form turned out to be Form 27B slash 6, which is referenced throughout the Index and has never been seen.]=] },
        { t = 16.18, text = [=[Several scholars believe it does not exist.]=] },
        { t = 20.34, text = [=[Zennit believes that is exactly what a form would say.]=] },
    },
    [5] = {
        { t = 0.41, text = [=[Meanwhile, the Ritual of Summoning, a spell with a great deal of free time and a fragile sense of self, had formed an attachment.]=] },
        { t = 9.63, text = [=[It does not want gold.]=] },
        { t = 12.53, text = [=[It wants, in its own words, attention and closure.]=] },
        { t = 17.38, text = [=[It will, however, accept fifty silver as a gesture.]=] },
    },
    [6] = {
        { t = 0.42, text = [=[And so every completed summon is recorded as an installment on a debt Zennit never agreed to, cannot find the paperwork for, and is nevertheless making definite progress on.]=] },
    },
    [7] = {
        { t = 0.42, text = [=[You, meanwhile, are a party of friends who have noticed that Zennit is, technically, very easy to summon.]=] },
        { t = 7.43, text = [=[The Index has no objection.]=] },
        { t = 10.94, text = [=[The Index has never been asked.]=] },
    },
    [8] = {
        { t = 0.41, text = [=[This is the story of his week, and every week after that.]=] },
        { t = 4.72, text = [=[If the form is ever found, you will be the first to know.]=] },
        { t = 9.14, text = [=[Or the last.]=] },
        { t = 11.54, text = [=[The Index is unclear.]=] },
    },
    [9] = {
        { t = 0.41, text = [=[The rules, such as they are.]=] },
        { t = 3.54, text = [=[Only summons of Zennit count; summons between friends are a pleasant way to spend an evening, and count for nothing.]=] },
        { t = 11.30, text = [=[Each week, the group earns points for the summons that land, with more points for places that are remote, or dangerous, or frankly unreasonable.]=] },
        { t = 20.94, text = [=[The Index files ten summons a week.]=] },
        { t = 24.76, text = [=[Anything more, it files under enthusiasm.]=] },
        { t = 29.23, text = [=[Zennit, for his part, holds a secret list of five places, which he will not discuss.]=] },
        { t = 35.28, text = [=[A summons to a place on it earns him the points as well.]=] },
        { t = 39.54, text = [=[If the group has more points at the end of the week, the Index records a victory for persistence.]=] },
    },
    [10] = {
        { t = 0.42, text = [=[If Zennit is not behind when the week ends, he wins the week, and goes on leave for the seven days that follow, when the race is off, and any summons of him is filed as disturbing his leave.]=] },
        { t = 12.80, text = [=[He may refuse a summons.]=] },
        { t = 15.80, text = [=[He may demand fifty silver, or whatever he fancies, in cash, with no receipt.]=] },
        { t = 21.92, text = [=[Or he may suggest dice, three times a week, though each helper may lean on the summoner's side.]=] },
        { t = 28.27, text = [=[Once five summons are filed, he may also close the Index until Monday.]=] },
        { t = 33.92, text = [=[When one side runs well ahead, the Index, which takes no sides, will lean toward the other.]=] },
        { t = 40.29, text = [=[Some weeks it has a whim.]=] },
        { t = 43.20, text = [=[The first to five weeks takes the season.]=] },
        { t = 47.41, text = [=[The Ritual, which has always wanted closure, approves.]=] },
        { t = 52.23, text = [=[The Index accepts most things.]=] },
    },
    [11] = {
        { t = 0.41, text = [=[At the end of the week, the Index counted.]=] },
        { t = 4.16, text = [=[It counted the summons, and the places, and the refusals, and the dice, and then it counted them again, because the total was not the one it had expected.]=] },
        { t = 14.05, text = [=[Zennit had won.]=] },
        { t = 16.68, text = [=[He had won the dice when it mattered, and he had been summoned, entirely by accident, to several of the places on his list.]=] },
    },
    [12] = {
        { t = 0.41, text = [=[The Index informed Zennit by registered letter, which he did not trust, and which he read twice.]=] },
        { t = 7.14, text = [=[For seven days, no ritual could find him.]=] },
        { t = 11.14, text = [=[The party gathered in a circle and said his name, and the Index replied that the Licensed Summoning Liaison was, regrettably, on leave.]=] },
        { t = 20.78, text = [=[Zennit spent the week doing nothing at all, which he had always suspected to be the correct amount.]=] },
    },
    [13] = {
        { t = 0.41, text = [=[The following week, the group won.]=] },
        { t = 3.79, text = [=[Nobody was more surprised than the group.]=] },
        { t = 7.79, text = [=[The Index counted the summons, and the places, and the refusals, and found that the party had finished ahead of Zennit, despite his head start, and despite a run of dice that had, until then, been entirely reliable.]=] },
        { t = 21.87, text = [=[The Index checked the sum three times.]=] },
        { t = 25.84, text = [=[It was not wrong.]=] },
    },
    [14] = {
        { t = 0.40, text = [=[A victory for persistence, as the rules had promised.]=] },
        { t = 5.04, text = [=[The party celebrated in the traditional manner, by summoning Zennit to the celebration.]=] },
        { t = 11.13, text = [=[He arrived, as he always did, slightly confused, and was handed a small cake, which he did not trust.]=] },
        { t = 18.53, text = [=[The Index recorded the week as a narrow win for hope over paperwork, and began, quietly, to count the next one.]=] },
    },
    [15] = {
        { t = 0.41, text = [=[Zennit's second week off began, as these things do, with a parcel.]=] },
        { t = 5.58, text = [=[Inside was a brass key, a luggage tag that said Side Door, and a note that said, helpfully, nothing.]=] },
        { t = 13.07, text = [=[He checked the key against his secret list.]=] },
        { t = 17.06, text = [=[It was the first item.]=] },
        { t = 20.08, text = [=[It had been the first item all along, and he had been too busy being summoned to read it.]=] },
    },
    [16] = {
        { t = 0.41, text = [=[The side door of the Index was exactly where the key said it would be, behind the letter Q, between a filing cabinet and a sign that said Please Do Not.]=] },
        { t = 10.73, text = [=[Zennit went in.]=] },
        { t = 13.13, text = [=[Beyond it was a quiet corridor, a very old kettle, and a desk with a chair that fit him suspiciously well.]=] },
        { t = 21.00, text = [=[He did not sit down.]=] },
        { t = 23.72, text = [=[He ticked the first item on his list, and somewhere in the Index, a clerk cleared his throat.]=] },
    },
    [17] = {
        { t = 0.42, text = [=[The group's second win arrived with an unexpected receipt.]=] },
        { t = 5.51, text = [=[Tucked into the cake box, under the napkins, was a sheet of faint blue carbon paper, which, held up to the light, showed the cover of a form.]=] },
        { t = 15.03, text = [=[The title was smudged.]=] },
        { t = 17.91, text = [=[The number was not.]=] },
        { t = 20.66, text = [=[It was Form 27B slash 6, or at least the part that had pressed through to the next page.]=] },
    },
    [18] = {
        { t = 0.40, text = [=[Scholars had always maintained that the form did not exist.]=] },
        { t = 5.35, text = [=[The carbon copy suggested otherwise.]=] },
        { t = 9.46, text = [=[It suggested that the form had once been filled in, by someone, in triplicate, and that the other two copies had gone to the Index and to the Ritual of Summoning.]=] },
        { t = 20.06, text = [=[The party kept the third.]=] },
        { t = 23.07, text = [=[The Index asked for it back.]=] },
        { t = 26.39, text = [=[The party said they would think about it.]=] },
    },
    [19] = {
        { t = 0.41, text = [=[Zennit's third week off began with the second item on his list, which was not an errand.]=] },
        { t = 6.71, text = [=[It was a pamphlet, titled Module One: Alphabetical Order.]=] },
        { t = 11.99, text = [=[The third item was Module Two: The Care and Feeding of Ink.]=] },
        { t = 17.29, text = [=[He understood, slowly, that the list had never been a list of errands.]=] },
        { t = 22.51, text = [=[It was a syllabus.]=] },
    },
    [20] = {
        { t = 0.42, text = [=[He studied in the corridor behind the side door, with the kettle for company.]=] },
        { t = 5.90, text = [=[By Friday he could recite the alphabet forwards, which the Index considered a promising start, and backwards, which it considered a gift.]=] },
        { t = 15.13, text = [=[On the desk, a nameplate was being engraved.]=] },
        { t = 19.50, text = [=[It had not yet been decided whose.]=] },
    },
    [21] = {
        { t = 0.41, text = [=[The group's third win was celebrated without cake, because the Ritual of Summoning had begun to answer back.]=] },
        { t = 8.01, text = [=[It did this in the only way a spell can, by glowing in a meaningful manner whenever the carbon copy was in the room.]=] },
        { t = 16.09, text = [=[The party found this unsettling.]=] },
        { t = 19.72, text = [=[They also found it encouraging.]=] },
        { t = 23.02, text = [=[It is possible to feel both.]=] },
    },
    [22] = {
        { t = 0.42, text = [=[The glow led them to a cellar beneath a tavern, where a chalk circle had been drawn on the floor so long ago that the tavern had been built on top of it.]=] },
        { t = 9.87, text = [=[In a crack at its centre, wedged tight, was a folded sheet of paper.]=] },
        { t = 15.19, text = [=[It was Form 27B slash 6.]=] },
        { t = 19.46, text = [=[The Ritual had been sitting on it for as long as anyone could remember, with the quiet pride of a spell that has finally been asked the right question.]=] },
    },
    [23] = {
        { t = 0.40, text = [=[In the fourth week, the clerk found Zennit in the corridor, reciting.]=] },
        { t = 5.37, text = [=[The clerk was very old and very tired, and had not left his desk since the invention of desks.]=] },
        { t = 12.41, text = [=[He looked at Zennit for a long time.]=] },
        { t = 16.00, text = [=["You are in the wrong book," he said.]=] },
        { t = 19.30, text = [=[Zennit replied that he had been told.]=] },
        { t = 23.08, text = [=[The clerk said that this was not a criticism.]=] },
    },
    [24] = {
        { t = 0.41, text = [=[The clerk showed him the desk.]=] },
        { t = 3.57, text = [=[It was enormous, and covered in nine thousand years of unfinished business, most of which turned out, on inspection, to be about Zennit.]=] },
        { t = 12.77, text = [=["I am not asking you to take it," said the clerk.]=] },
        { t = 16.46, text = [=["I am only asking you to hold the pen, while I find my hat."]=] },
    },
    [25] = {
        { t = 0.41, text = [=[The Ritual of Summoning, once asked, was only too happy to talk.]=] },
        { t = 5.51, text = [=[It had never wanted gold, it explained.]=] },
        { t = 9.52, text = [=[It had wanted a proper ending: a last summons, performed with attention, followed by closure.]=] },
        { t = 16.08, text = [=[It had been waiting for one since before the tavern.]=] },
        { t = 20.28, text = [=[It was very good about it.]=] },
    },
    [26] = {
        { t = 0.40, text = [=[The price was modest.]=] },
        { t = 3.30, text = [=[Fifty silver, paid in person, in cash.]=] },
        { t = 7.60, text = [=[And the third copy of the form, to complete the set.]=] },
        { t = 11.79, text = [=[The Ritual had waited a very long time for the set.]=] },
        { t = 16.28, text = [=[It understood how that looked, and said so, which the party agreed was decent of it.]=] },
    },
    [27] = {
        { t = 0.40, text = [=[In the fifth week, the clerk found his hat.]=] },
        { t = 4.14, text = [=[It was on his head.]=] },
        { t = 6.63, text = [=[He said this was the sort of thing that happens to a person who has looked at nothing but the Index for nine thousand years.]=] },
        { t = 15.35, text = [=[He shook Zennit's hand, left through the side door, and was last seen walking toward the sea, without his coat, visibly lighter.]=] },
    },
    [28] = {
        { t = 0.40, text = [=[Zennit sat down.]=] },
        { t = 3.11, text = [=[The chair fit, as expected.]=] },
        { t = 6.51, text = [=[He read the Index from the beginning, which took a week, and found it sound, apart from the letter Z, where one entry had been smudged and then misfiled by a sneeze.]=] },
        { t = 17.09, text = [=[He corrected it with a single stroke of the pen.]=] },
        { t = 20.96, text = [=[Somewhere far below, the Ritual of Summoning went quiet.]=] },
    },
    [29] = {
        { t = 0.41, text = [=[Then he did what no clerk had done in nine thousand years.]=] },
        { t = 5.42, text = [=[He added entries.]=] },
        { t = 8.20, text = [=[The party went in first, in alphabetical order, each with a short note of thanks.]=] },
        { t = 14.17, text = [=[Zennit, Licensed Summoning Liaison, Third Class, was promoted to Clerk, and invited the party to summon him whenever they liked.]=] },
        { t = 23.10, text = [=[He would, of course, always accept.]=] },
        { t = 26.67, text = [=[The Index wrote that down.]=] },
    },
    [30] = {
        { t = 0.42, text = [=[On the group's fifth win, the party went down into the cellar with fifty silver in cash, the third copy of the form, and the kind of nerves usually reserved for exams.]=] },
        { t = 11.76, text = [=[The Ritual of Summoning glowed.]=] },
        { t = 15.24, text = [=[It was clear that it, too, had prepared something.]=] },
    },
    [31] = {
        { t = 0.40, text = [=[The silver was counted.]=] },
        { t = 3.49, text = [=[The copy was handed over.]=] },
        { t = 6.84, text = [=[The Ritual, for the first time in its existence, was given a receipt: Form 27B slash 6, complete in triplicate, and stamped.]=] },
        { t = 16.32, text = [=[The Index approved, from a distance.]=] },
        { t = 19.86, text = [=[Closure, it turned out, was mostly paperwork.]=] },
    },
    [32] = {
        { t = 0.40, text = [=[The Ritual let go.]=] },
        { t = 3.16, text = [=[Zennit felt it as a small click, like a lock turning in a door he had never noticed.]=] },
        { t = 9.13, text = [=[For the first time in his life, he was summoned by nobody.]=] },
        { t = 13.36, text = [=[He stood in the cellar, free.]=] },
        { t = 16.53, text = [=[Then he did the only thing he could think of, and summoned the party to his place, for cake.]=] },
        { t = 22.37, text = [=[They accepted.]=] },
        { t = 24.73, text = [=[It was, by general agreement, a very small cake.]=] },
    },
    [34] = {
        { t = 0.42, text = [=[For nine thousand years, nobody added anything to the Index.]=] },
        { t = 5.48, text = [=[Then Zennit, newly Clerk, added an entire party, in alphabetical order, with notes of thanks.]=] },
        { t = 12.52, text = [=[Somewhere in a building that does not appear on any map, a bell rang that had never rung before.]=] },
        { t = 18.95, text = [=[It was the bell for audits.]=] },
        { t = 21.94, text = [=[Nobody saw who rang it.]=] },
    },
    [35] = {
        { t = 0.41, text = [=[The Auditor arrived on a Monday, with a stamp and a hat slightly too large.]=] },
        { t = 5.90, text = [=[The Auditor found the chair in order, the pen in order, and the clerk not in order at all, having been entered in the wrong book.]=] },
        { t = 14.30, text = [=[Zennit was moved, gently, to pending review.]=] },
        { t = 18.63, text = [=[Until the audit closed, he was to present himself whenever summoned, as evidence.]=] },
        { t = 24.40, text = [=[He accepted.]=] },
        { t = 26.77, text = [=[He accepts everything now.]=] },
        { t = 30.12, text = [=[He has been asked to stop apologising.]=] },
    },
    [36] = {
        { t = 0.41, text = [=[A receipt issued by a spell is, in the Index's view, irregular.]=] },
        { t = 5.74, text = [=[A receipt issued by a spell to itself is a matter for audit.]=] },
        { t = 10.79, text = [=[The bell for audits, which had not rung in nine thousand years, rang.]=] },
        { t = 16.14, text = [=[Nobody saw who rang it.]=] },
    },
    [37] = {
        { t = 0.42, text = [=[The Auditor arrived on a Monday, with a stamp and a hat slightly too large, and suspended the receipt pending review.]=] },
        { t = 8.43, text = [=[Zennit, who had been free for almost a week and was just getting used to it, felt the small click again, in reverse.]=] },
        { t = 16.00, text = [=[He was entered as pending review, summonable as evidence until the audit closed.]=] },
        { t = 22.06, text = [=[The Ritual apologised.]=] },
        { t = 25.16, text = [=[The Auditor noted the apology as evidence too.]=] },
    },
    [38] = {
        { t = 0.41, text = [=[Zennit's first week off of the audit was filed, by the Auditor, as gardening leave pending audit.]=] },
        { t = 7.06, text = [=[Zennit did not have a garden.]=] },
        { t = 10.26, text = [=[He spent the week in a borrowed deckchair, beside a patch of earth the Index had provided for the purpose, wondering what, exactly, was being audited.]=] },
        { t = 19.92, text = [=[On the Friday, he asked to see his file.]=] },
    },
    [39] = {
        { t = 0.40, text = [=[The Auditor did not open the file.]=] },
        { t = 3.94, text = [=[The Auditor recited it: every summons of Zennit, with the date, the place, and what he had said, without once looking down.]=] },
        { t = 12.04, text = [=[Zennit found this impressive.]=] },
        { t = 15.19, text = [=[He also found it odd, in the way that a dog knowing your birthday is odd.]=] },
        { t = 20.88, text = [=[He said nothing, and made a note.]=] },
    },
    [40] = {
        { t = 0.41, text = [=[His file, when it came, was very thin.]=] },
        { t = 4.49, text = [=[It held his name, the sneeze, and a note in the margin that said see also.]=] },
        { t = 10.08, text = [=[There was nothing to see also.]=] },
        { t = 13.31, text = [=[Zennit, who had studied the syllabus, did what the syllabus had taught him.]=] },
        { t = 18.21, text = [=[He looked the Auditor up in the Index, under A.]=] },
    },
    [41] = {
        { t = 0.41, text = [=[There was no Auditor under A.]=] },
        { t = 4.03, text = [=[There was no Auditor under Z, or under the sneeze, or anywhere at all.]=] },
        { t = 9.39, text = [=[The Index had never had an Auditor.]=] },
        { t = 13.21, text = [=[It had a bell for audits, because it had a bell for everything, but nobody had ever been appointed to answer it.]=] },
        { t = 20.07, text = [=[Zennit wrote one question at the top of a clean page.]=] },
        { t = 24.37, text = [=[Who rang the bell?]=] },
    },
    [42] = {
        { t = 0.42, text = [=[The bell for audits hung at the end of a corridor nobody used.]=] },
        { t = 5.45, text = [=[Its rope was new.]=] },
        { t = 8.09, text = [=[It had been frayed, recently, at the height of an ordinary person, by someone who had pulled it with feeling.]=] },
        { t = 15.15, text = [=[The dust beneath it had been disturbed by a pair of ordinary boots, which had walked in, and stood, and walked out again, in a hurry.]=] },
    },
    [43] = {
        { t = 0.40, text = [=[In the dust, where the boots had stood, was a soul shard.]=] },
        { t = 4.90, text = [=[It was small, and purple, and faintly warm, the kind warlocks keep in a bag and lose down the back of the sofa.]=] },
        { t = 12.81, text = [=[Zennit picked it up and turned it over.]=] },
        { t = 16.43, text = [=[He knew several warlocks.]=] },
        { t = 19.28, text = [=[He knew most of them rather well.]=] },
        { t = 22.53, text = [=[He put the shard in his pocket, and went to see the Auditor.]=] },
    },
    [44] = {
        { t = 0.40, text = [=[In the fourth week, Zennit asked the Auditor for a favour.]=] },
        { t = 4.87, text = [=[Would the Auditor summon him, he asked, for the evidence?]=] },
        { t = 9.11, text = [=[The Auditor hesitated, which auditors do not do.]=] },
        { t = 13.69, text = [=[Then the Auditor stepped outside, gathered two helpers, and began.]=] },
        { t = 18.96, text = [=[No book was opened.]=] },
        { t = 21.82, text = [=[No notes were consulted.]=] },
        { t = 24.70, text = [=[The ritual was cast from memory, in under a minute.]=] },
    },
    [45] = {
        { t = 0.41, text = [=[Zennit arrived where he always arrived, slightly confused, and then not confused at all.]=] },
        { t = 6.81, text = [=[He knew that ritual.]=] },
        { t = 9.54, text = [=[He had been on the other end of it every week for a season: the same pace, the same flourish at the end, the same small impatience in the middle.]=] },
        { t = 18.70, text = [=[He thanked the Auditor, politely.]=] },
        { t = 22.05, text = [=[He said nothing else.]=] },
        { t = 24.87, text = [=[He did not need to.]=] },
    },
    [46] = {
        { t = 0.40, text = [=[In the fifth week, Zennit closed the audit himself, by procedure.]=] },
        { t = 5.37, text = [=[An audit, the syllabus said, closes when the auditor is entered in the Index.]=] },
        { t = 11.02, text = [=[He uncapped the pen and asked the Auditor, politely, to spell their name.]=] },
        { t = 16.56, text = [=[The Auditor looked at the pen for a long time.]=] },
        { t = 20.28, text = [=[Then the Auditor took off the hat, which had always been slightly too large.]=] },
        { t = 25.57, text = [=[It was Poogs.]=] },
    },
    [47] = {
        { t = 0.40, text = [=[Poogs explained.]=] },
        { t = 2.95, text = [=[When the last season ended, he had worked out that Zennit would never be summoned again, and he had not been ready for that.]=] },
        { t = 10.72, text = [=[So he had rung the bell himself, borrowed a stamp, and bought a hat.]=] },
        { t = 15.52, text = [=[Pending review meant summonable.]=] },
        { t = 18.97, text = [=[That was all he had wanted.]=] },
        { t = 22.01, text = [=[He was very sorry.]=] },
        { t = 24.77, text = [=[He was not, entirely, sorry.]=] },
    },
    [48] = {
        { t = 0.41, text = [=[Zennit wrote a new entry, under P, in ink.]=] },
        { t = 4.77, text = [=[It said: Poogs.]=] },
        { t = 7.55, text = [=[Summons Zennit, persistently.]=] },
        { t = 10.72, text = [=[Not an offence.]=] },
        { t = 13.15, text = [=[He stamped it Correct, a stamp that had never been used before.]=] },
        { t = 17.82, text = [=[Then he handed Poogs back his hat, and his soul shard, and said: same time next week.]=] },
        { t = 24.37, text = [=[The Index wrote that down.]=] },
    },
    [49] = {
        { t = 0.40, text = [=[The group's first win of the audit was rewarded in an unexpected way.]=] },
        { t = 5.63, text = [=[The party was summoned, all at once, by a ritual nobody in the room had cast, to a hall with a long table and a small sign that said Witnesses.]=] },
        { t = 15.36, text = [=[They arrived slightly confused, one of them still holding a fork.]=] },
        { t = 20.17, text = [=[All of them, that is, but Poogs, who sent apologies.]=] },
    },
    [50] = {
        { t = 0.41, text = [=[The Auditor accepted the apologies without looking up.]=] },
        { t = 5.17, text = [=[Witnesses, the Auditor explained, are summoned, not invited, because an invitation can be declined.]=] },
        { t = 12.35, text = [=[Zennit, at the far end of the table, was very understanding about it.]=] },
        { t = 17.34, text = [=[He handed round a leaflet titled So You Have Been Summoned.]=] },
        { t = 21.90, text = [=[He had written it himself, years ago, and never had anyone to give it to.]=] },
    },
    [51] = {
        { t = 0.41, text = [=[The group's second win produced the evidence: a notebook.]=] },
        { t = 5.26, text = [=[In it was every summons of Zennit, with the date, the place, the helpers, and what he had said.]=] },
        { t = 11.47, text = [=[Nobody at the table remembered keeping it.]=] },
        { t = 15.41, text = [=[The handwriting was neat, and slanted, and familiar, and nobody could quite say why.]=] },
        { t = 21.70, text = [=[Poogs, once again, had sent apologies.]=] },
    },
    [52] = {
        { t = 0.41, text = [=[The Auditor stamped the notebook Received, rather quickly, and entered it as Exhibit A.]=] },
        { t = 6.61, text = [=[The party took this as a compliment, which the Auditor allowed.]=] },
        { t = 11.34, text = [=[Zennit asked if he could see it.]=] },
        { t = 14.62, text = [=[The Auditor said: after the audit.]=] },
        { t = 18.14, text = [=[Zennit said he had a feeling about that.]=] },
        { t = 21.91, text = [=[He did.]=] },
        { t = 23.95, text = [=[It was the same feeling he had about most things, but stronger.]=] },
    },
    [53] = {
        { t = 0.41, text = [=[On the group's third win, the Ritual of Summoning asked to give evidence.]=] },
        { t = 5.80, text = [=[Nobody had called it.]=] },
        { t = 8.54, text = [=[It turned up, glowing, in the witness chair, which was not built for a spell, with a statement about Zennit.]=] },
        { t = 15.13, text = [=[The statement was mostly kind, and slightly too long.]=] },
        { t = 20.14, text = [=[He always came, it said, even when he complained, and he complained very well.]=] },
    },
    [54] = {
        { t = 0.41, text = [=[Halfway through, the Ritual noticed the Auditor, and glowed warmly, the way it glows at people it knows well.]=] },
        { t = 8.03, text = [=["Oh, hello," it said.]=] },
        { t = 10.99, text = [=["We work together most Tuesdays." The Auditor coughed, and wrote something down.]=] },
        { t = 17.14, text = [=[The Ritual, realising it had said something, glowed in the wrong places for the rest of the afternoon.]=] },
        { t = 23.85, text = [=[The party noted the glow.]=] },
        { t = 27.00, text = [=[They did not note the cough.]=] },
    },
    [55] = {
        { t = 0.40, text = [=[On the group's fourth win, the Auditor closed the notebook, set down the stamp, and asked the party the only question the audit had.]=] },
        { t = 9.13, text = [=["Why do you keep summoning him?" It was not unkind.]=] },
        { t = 13.45, text = [=[For a moment, it sounded less like a question than a confession, though nobody at the table could have said whose.]=] },
    },
    [56] = {
        { t = 0.40, text = [=[The party looked at one another.]=] },
        { t = 3.55, text = [=[Several answers were offered, none of which were filed.]=] },
        { t = 7.95, text = [=[The Auditor said there was no hurry: the answer would be due at the close of the audit, in writing, in triplicate.]=] },
        { t = 15.49, text = [=[The party went home and thought about it.]=] },
        { t = 19.20, text = [=[So, they would later realise, did the Auditor.]=] },
    },
    [57] = {
        { t = 0.41, text = [=[On the group's fifth win, the party came back to the long table with their answer, in triplicate.]=] },
        { t = 6.66, text = [=[It was one line long.]=] },
        { t = 9.40, text = [=[They had argued about it for a week and crossed out a great deal, and what was left said: "Because he comes." The Auditor read it three times, once per copy, which is procedure.]=] },
        { t = 20.96, text = [=[Then the Auditor took off the hat.]=] },
    },
    [58] = {
        { t = 0.40, text = [=[It was Poogs.]=] },
        { t = 2.89, text = [=[He had missed every session as a witness because he had been at every session as the Auditor.]=] },
        { t = 9.20, text = [=[When the last season ended, he explained, he had not been ready to stop summoning Zennit.]=] },
        { t = 15.03, text = [=[So he had rung the bell himself.]=] },
        { t = 18.49, text = [=[The party said they had suspected since the notebook.]=] },
        { t = 23.01, text = [=[They had not.]=] },
        { t = 25.26, text = [=[Zennit said he had.]=] },
        { t = 27.99, text = [=[He had.]=] },
    },
    [59] = {
        { t = 0.42, text = [=[Poogs wrote the finding himself, and stamped it, in triplicate: Zennit had been summoned persistently, unreasonably, and out of affection, which is not an offence.]=] },
        { t = 11.09, text = [=[He filed himself under it first.]=] },
        { t = 14.60, text = [=[Then Zennit was handed a new form, a Request to Be Summoned.]=] },
        { t = 19.35, text = [=[He filled it in at once and gave it to Poogs.]=] },
        { t = 23.22, text = [=[It was, by general agreement, a slightly larger cake.]=] },
    },
}
